import { ContactSignals } from './Signals'
import { useCallback, useEffect, useRef, useState } from 'react'
import { ArrowDownToLine, ArrowRight, Check, Copy, FileText, LoaderCircle, Mail, MessageSquare, Phone, Plus, RefreshCw, Search, Settings2, SlidersHorizontal, ChevronDown, Users } from 'lucide-react'
import { api, activeRun, channelLabels, formatDate, stageLabels, type ScanningState, type Contact, type CRMContact, type Health, type Interaction, type Query, type Run, type Script, type ScriptStat, type ScoutRun, type SharedStatus, type LocalModelStatus, type Answer, opportunityLabels } from './types'
import { Avatar, Modal } from './ui'

const message = (e:unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
const post = (body:unknown):RequestInit => ({method:'POST',body:JSON.stringify(body)})
function ErrorBox({error}:{error:string}) { return error ? <div className="error-text" role="alert">{error}</div> : null }
function Busy({busy}:{busy:boolean}) { return busy ? <LoaderCircle className="spin" size={15}/> : null }
const dateInput = (value:string|null) => value ? new Date(new Date(value).getTime()-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16) : ''
const dateValue = (value:string) => value ? new Date(value).toISOString() : null

type Dashboard = {series:{date:string;identified:number;qualified:number;contacted:number;demos:number}[];totals:Record<string,number>;agenda:Record<string,number>}
export function DashboardPanel({revision,onView}:{revision:number;onView:(view:string)=>void}) {
  const [days,setDays]=useState('30'),[data,setData]=useState<Dashboard|null>(null),[error,setError]=useState('')
  const [hidden,setHidden]=useState<string[]>([]),[hover,setHover]=useState<number|null>(null)
  const currentDays=useRef(days); currentDays.current=days
  useEffect(()=>{void api<Dashboard>('/api/dashboard?days='+days).then(d=>{if(currentDays.current===days){setData(d);setError('')}}).catch(e=>{if(currentDays.current===days)setError(message(e))})},[days,revision])
  const lines=[{key:'identified',label:'Personas identificadas',color:'#2c7958',dash:undefined},{key:'qualified',label:'Contactos potenciales',color:'#79a143',dash:'8 4'},{key:'contacted',label:'Personas contactadas',color:'#608fa8',dash:'3 4'},{key:'demos',label:'Demos / reuniones',color:'#c09744',dash:'12 4 3 4'}] as const
  const series=data?.series||[],visible=lines.filter(line=>!hidden.includes(line.key)),maximum=Math.max(4,Math.ceil(Math.max(0,...series.flatMap(row=>visible.map(line=>row[line.key])))/4)*4)
  const x=(index:number)=>48+(series.length<2?0:index/(series.length-1)*828),y=(value:number)=>238-value/maximum*208
  const picked=hover!==null?series[hover]:null
  const shortDate=(date:string)=>new Date(date+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'short'})
  return <section className="commercial-overview"><div className="evolution panel"><div className="section-line"><div><h2>Evolución comercial</h2><p>Personas únicas por día · compara las cuatro líneas en la misma escala</p></div><select aria-label="Periodo de las gráficas" value={days} onChange={e=>setDays(e.target.value)}><option value="7">Últimos 7 días</option><option value="30">Últimos 30 días</option><option value="0">Todo el historial</option></select></div><ErrorBox error={error}/>
    <div className="chart-legend">{lines.map(line=><button key={line.key} aria-pressed={!hidden.includes(line.key)} onClick={()=>setHidden(current=>current.includes(line.key)?current.filter(k=>k!==line.key):[...current,line.key])}><i style={{background:line.color}}/><span>{line.label}</span><strong>{series.reduce((sum,row)=>sum+row[line.key],0)}</strong></button>)}</div>
    <div className="combined-chart"><svg viewBox="0 0 900 260" preserveAspectRatio="none" role="img" aria-label="Gráfica conjunta de personas identificadas, contactos potenciales, personas contactadas y demos" onPointerMove={event=>{const rect=event.currentTarget.getBoundingClientRect();setHover(Math.max(0,Math.min(series.length-1,Math.round(((event.clientX-rect.left)/rect.width*900-48)/828*(series.length-1)))));}} onPointerLeave={()=>setHover(null)}>
      <title>Cuatro series por día en una misma gráfica</title>{[0,1,2,3,4].map(step=><g key={step}><line x1="48" x2="876" y1={y(maximum*step/4)} y2={y(maximum*step/4)} stroke="#e5ebdf" strokeDasharray={step?'3 4':undefined}/><text x="32" y={y(maximum*step/4)+5} textAnchor="end" fill="#8c9985" fontSize="13">{maximum*step/4}</text></g>)}
      {visible.map(line=><g key={line.key} data-series={line.key}><polyline points={series.map((row,index)=>x(index)+','+y(row[line.key])).join(' ')} fill="none" stroke={line.color} strokeWidth="2.5" strokeDasharray={line.dash} vectorEffect="non-scaling-stroke"/>{series.map((row,index)=>row[line.key]>0&&<circle key={index} cx={x(index)} cy={y(row[line.key])} r="3.5" fill={line.color}><title>{line.label+' · '+row.date+': '+row[line.key]}</title></circle>)}</g>)}
      {picked&&hover!==null&&<line x1={x(hover)} x2={x(hover)} y1="25" y2="240" stroke="#98aa8a" strokeDasharray="4 4"/>}
    </svg><div className="chart-dates">{series.length>0&&[0,Math.floor((series.length-1)/2),series.length-1].filter((value,index,values)=>values.indexOf(value)===index).map(index=><span key={index}>{shortDate(series[index].date)}</span>)}</div>
    <div className="chart-readout" aria-live="polite">{picked?<><strong>{shortDate(picked.date)}</strong>{lines.map(line=><span key={line.key} style={{color:line.color}}>{line.label}: <b>{picked[line.key]}</b></span>)}</>:<span>Pasa el cursor para consultar un día. Pulsa una leyenda para mostrar u ocultar su línea.</span>}</div></div><small>Un perfil actualizado no cuenta como nuevo.</small></div>
    <aside className="agenda panel"><div className="section-line"><h2>Agenda comercial</h2><Users size={18}/></div>{[{id:'all',label:'Lista completa'},{id:'pending',label:'Por escribir o llamar'},{id:'followups',label:'Seguimientos'},{id:'burned',label:'Ya contactados / quemados'}].map(v=><button key={v.id} onClick={()=>onView(v.id)}><span>{v.label}</span><b>{data?.agenda[v.id]??0}</b><ArrowRight size={14}/></button>)}</aside>
  </section>
}

export function ContactWorkspace({includeIncomplete=false,search='',segment='',qualification='all',contacts,health,run,revision,view,onView,onRefresh,onRun,onAdd,onReview}:{contacts:Contact[];health:Health|null;run:Run|null;revision:number;view:string;onView:(v:string)=>void;onRefresh:()=>void;onRun:(r:Run)=>void;onAdd:()=>void;onReview:(c:Contact)=>void;qualification?:string;search?:string;segment?:string;includeIncomplete?:boolean}) {
  // Arriving from another page shows every profile that matches the requested firm or subsector.
  const [filters,setFilters]=useState({q:search,status:qualification,stage:'',country:'',role:'',min_score:'0',size:'',channel:'',owner:'',letter:'',reachability:includeIncomplete||search||segment?'all':'reachable',signals:'all',opportunity:'all',sort:'name',segment}),[page,setPage]=useState(1)
  const [rows,setRows]=useState<CRMContact[]>([]),[total,setTotal]=useState(0),[error,setError]=useState(''),[loading,setLoading]=useState(false)
  const [advanced,setAdvanced]=useState(false)
  const [selected,setSelected]=useState<number[]>([]),[detail,setDetail]=useState<{contact:CRMContact;channel?:string}|null>(null),[busy,setBusy]=useState(false)
  const set=(key:keyof typeof filters,value:string)=>{setFilters(f=>({...f,[key]:value}));setPage(1);setSelected([])}
  const params=new URLSearchParams({...filters,page:String(page),view}); params.delete('size')
  if(filters.size){const [lo,hi]=filters.size.split('-');params.set('size_min',lo);params.set('size_max',hi)}
  const paramString=params.toString()
  useEffect(()=>{setPage(1);setSelected([])},[view])
  useEffect(()=>{setFilters(f=>({...f,q:search}));setPage(1)},[search])
  useEffect(()=>{setFilters(f=>({...f,segment}));setPage(1)},[segment])
  const [segmentLabels,setSegmentLabels]=useState<Record<string,string>>({})
  useEffect(()=>{void api<{labels:Record<string,string>}>('/api/segments').then(d=>setSegmentLabels(d.labels)).catch(()=>{})},[])
  useEffect(()=>{setFilters(f=>({...f,status:qualification}));setPage(1);setSelected([])},[qualification])
  // A background refresh never discards a load in progress: any answer for the current filters is shown.
  const currentParams=useRef(paramString); currentParams.current=paramString
  useEffect(()=>{setLoading(true);void api<{items:CRMContact[];total:number}>('/api/crm/contacts?'+paramString).then(d=>{if(currentParams.current===paramString){setRows(d.items);setTotal(d.total);setError('')}}).catch(e=>{if(currentParams.current===paramString)setError(message(e))}).finally(()=>{if(currentParams.current===paramString)setLoading(false)})},[paramString,revision])
  const owners=Array.from(new Set(contacts.map(c=>(c as CRMContact).owner).filter(Boolean))).sort()
  const roles=Array.from(new Set(contacts.map(c=>c.role).filter(Boolean))).sort()
  async function publicSearch(){setBusy(true);setError('');try{await api('/api/public/searches',post({contact_ids:selected,continuous:false}));onRefresh();setSelected([])}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function enrich(phone:boolean){setBusy(true);setError('');try{onRun(await api<Run>('/api/apollo/enrich',post({contact_ids:selected,phone})));setSelected([])}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function restore(c:CRMContact){setBusy(true);setError('');try{await api('/api/crm/contacts/'+c.id+'/quality',{method:'PUT',body:JSON.stringify({status:'ok'})});onRefresh()}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function rescan(c:CRMContact){setBusy(true);setError('');try{onRun(await api<Run>('/api/crm/contacts/'+c.id+'/rescan',post({provider:'web'})))}catch(e){setError(message(e))}finally{setBusy(false)}}
  return <section className="crm-workspace"><div className="results-heading"><div><h2>Tu lista permanente</h2><p>Conversaciones, próximos pasos y resultados en un mismo lugar.</p></div><div className="results-actions"><button className="secondary small" onClick={onAdd}><Plus size={15}/>Añadir contacto</button><a className="secondary small" href={'/api/crm/contacts/export?'+paramString}><ArrowDownToLine size={15}/>Exportar lista filtrada</a><a className="text-button" href="/api/crm/contacts/export">CSV completo</a></div></div>
    <div className="tabs">{[{id:'all',label:'Todos'},{id:'pending',label:'Por escribir / llamar'},{id:'followups',label:'Seguimientos'},{id:'burned',label:'Ya contactados'},{id:'junk',label:'Ocultados por Qwen'}].map(v=><button key={v.id} className={view===v.id?'active':''} onClick={()=>onView(v.id)}>{v.label}</button>)}</div>
    <div className="simple-filters"><label className="filter-search"><Search size={18}/><input aria-label="Buscar en agenda" placeholder="Busca una persona o gestora…" value={filters.q} onChange={e=>set('q',e.target.value)}/></label><select aria-label="Calificación de agenda" value={filters.status} onChange={e=>set('status',e.target.value)}><option value="all">Todos los contactos</option><option value="qualified">Encajan con el objetivo</option><option value="review">Por verificar</option><option value="excluded">Fuera del objetivo</option></select><label className="score-filter">Puntuación mínima<input aria-label="Puntuación mínima" type="number" min="0" max="100" value={filters.min_score} onChange={e=>set('min_score',String(Math.min(100,Math.max(0,Number(e.target.value)||0))))}/></label><select aria-label="Datos de contacto disponibles" value={filters.reachability} onChange={e=>set('reachability',e.target.value)}><option value="reachable">Con LinkedIn, correo o teléfono</option><option value="missing">Sin datos de contacto · revisar</option><option value="all">Todos los perfiles</option></select><button className={'secondary filter-toggle '+(advanced?'is-open':'')} aria-expanded={advanced} aria-controls="extra-contact-filters" onClick={()=>setAdvanced(v=>!v)}><SlidersHorizontal size={16}/>Más filtros{[filters.stage,filters.country,filters.role,filters.size,filters.channel,filters.owner,filters.min_score!=='0'?filters.min_score:'',filters.signals!=='all'?filters.signals:'',filters.opportunity!=='all'?filters.opportunity:'',filters.sort!=='name'?filters.sort:'',filters.segment].filter(Boolean).length>0&&<b>{[filters.stage,filters.country,filters.role,filters.size,filters.channel,filters.owner,filters.min_score!=='0'?filters.min_score:'',filters.signals!=='all'?filters.signals:'',filters.opportunity!=='all'?filters.opportunity:'',filters.sort!=='name'?filters.sort:'',filters.segment].filter(Boolean).length}</b>}<ChevronDown size={14}/></button>{Object.entries(filters).some(([key,value])=>(key==='status'||key==='signals'||key==='opportunity')?value!=='all':key==='sort'?value!=='name':key==='min_score'?value!=='0':key==='reachability'?value!=='reachable':!!value)&&<button className="text-button" onClick={()=>{setFilters({q:'',status:'all',stage:'',country:'',role:'',min_score:'0',size:'',channel:'',owner:'',letter:'',reachability:'reachable',signals:'all',opportunity:'all',sort:'name',segment:''});setPage(1);setSelected([])}}>Limpiar filtros</button>}</div>
    {advanced&&<div className="advanced-filters panel" id="extra-contact-filters"><div className="form-grid"><label>Subsector<select aria-label="Subsector de la gestora" value={filters.segment} onChange={e=>set('segment',e.target.value)}><option value="">Todos los subsectores</option>{Object.entries(segmentLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Oportunidad comercial<select aria-label="Oportunidad comercial" value={filters.opportunity} onChange={e=>set('opportunity',e.target.value)}><option value="all">Cualquier oportunidad</option>{Object.entries(opportunityLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>Orden<select aria-label="Orden de agenda" value={filters.sort} onChange={e=>set('sort',e.target.value)}><option value="name">Por nombre</option><option value="opportunity">Mayor oportunidad primero</option></select></label><label>Señales recientes<select aria-label="Señales de la gestora" value={filters.signals} onChange={e=>set('signals',e.target.value)}><option value="all">Todas las gestoras</option><option value="recent">Con publicaciones recientes fechadas</option><option value="review">Con señales por revisar</option><option value="event_driven">Estrategia event-driven</option></select></label><label>Etapa<select aria-label="Etapa comercial" value={filters.stage} onChange={e=>set('stage',e.target.value)}><option value="">Todas las etapas</option>{Object.entries(stageLabels).map(([k,v])=><option key={k} value={k}>{v}</option>)}</select></label><label>País<select aria-label="País de agenda" value={filters.country} onChange={e=>set('country',e.target.value)}><option value="">Todos los países</option>{health?.countries.map(c=><option key={c}>{c}</option>)}</select></label><label>Cargo<select aria-label="Cargo de agenda" value={filters.role} onChange={e=>set('role',e.target.value)}><option value="">Todos los cargos</option>{roles.map(r=><option key={r}>{r}</option>)}</select></label><label>Tamaño<select aria-label="Tamaño de agenda" value={filters.size} onChange={e=>set('size',e.target.value)}><option value="">Todo tamaño</option><option value="5-20">5–20 empleados</option><option value="21-50">21–50 empleados</option><option value="51-200">51–200 empleados</option></select></label><label>Canal<select aria-label="Canal disponible" value={filters.channel} onChange={e=>set('channel',e.target.value)}><option value="">Cualquier canal</option><option value="call">Con teléfono</option><option value="email">Con correo</option><option value="linkedin">Con LinkedIn</option></select></label><label>Responsable<select aria-label="Responsable de agenda" value={filters.owner} onChange={e=>set('owner',e.target.value)}><option value="">Todos los responsables</option>{owners.map(o=><option key={o}>{o}</option>)}</select></label></div></div>}

    <ErrorBox error={error}/>{selected.length>0&&<div className="bulk-toolbar"><strong>{selected.length} seleccionados</strong><button className="primary small" disabled={busy} onClick={()=>void publicSearch()}><Search size={14}/>Buscar datos públicos</button><span>Apollo opcional: completar datos puede usar créditos.</span><button className="secondary small" disabled={busy||activeRun(run)} onClick={()=>void enrich(false)}><Mail size={14}/>Completar correo</button><button className="secondary small" disabled={busy||activeRun(run)} onClick={()=>void enrich(true)}><Phone size={14}/>Completar teléfono</button></div>}
    <div className="table-scroll panel"><table className="contact-table"><thead><tr><th><input type="checkbox" aria-label="Seleccionar página" checked={rows.length>0&&rows.filter(c=>!c.blocked).every(c=>selected.includes(c.id))} onChange={e=>setSelected(e.target.checked?rows.filter(c=>!c.blocked).map(c=>c.id):[])}/></th><th>Persona / gestora</th><th>Encaje / oportunidad</th><th>Contacto</th><th>Seguimiento</th><th>Acciones</th></tr></thead><tbody>{rows.map(c=><tr key={c.id}><td><input type="checkbox" aria-label={'Seleccionar '+c.name} disabled={c.blocked} checked={selected.includes(c.id)} onChange={e=>setSelected(s=>e.target.checked?[...s,c.id]:s.filter(id=>id!==c.id))}/></td><td><div className="table-person">{c.linkedin_url?<a href={c.linkedin_url} target="_blank" rel="noopener noreferrer"><Avatar contact={c}/></a>:<Avatar contact={c}/>}<div>{c.linkedin_url?<a className="person-link" href={c.linkedin_url} target="_blank" rel="noopener noreferrer">{c.name} ↗</a>:<button className="person-link" onClick={()=>setDetail({contact:c})}>{c.name}</button>}<span>{c.role||'Cargo por verificar'}</span><small className="profile-origin">{c.linkedin_url?<a href={c.linkedin_url} target="_blank" rel="noopener noreferrer">Perfil de LinkedIn ↗</a>:<>Fuente web · sin LinkedIn</>}{c.photo_url&&' · Foto '+(c.photo_origin||'pública')}</small><small>{c.company} · {c.country||'País pendiente'}{c.segment_label?' · '+c.segment_label:''}</small></div></div></td><td><b>{c.score}/100</b><small>{c.status==='qualified'?'Objetivo':c.status==='review'?'Por verificar':'Fuera del objetivo'}</small>{c.quality?.status==='junk'&&<><small className="junk-reason">Oculto ({c.quality.by}): {c.quality.reason}</small><button className="text-button" onClick={()=>void restore(c)}>No es basura · restaurar</button></>}{c.quality?.status==='doubtful_firm'&&<small className="junk-reason">Gestora dudosa ({c.quality.by}): {c.quality.reason}</small>}<small className={'opportunity-pill '+c.opportunity_status}>Oportunidad {c.opportunity_score}/100 · {opportunityLabels[c.opportunity_status]}</small>{!!c.recent_signal_count&&<small className="signal-count">{c.recent_signal_count} señales recientes</small>}</td><td>{c.linkedin_url&&<a href={c.linkedin_url} target="_blank" rel="noopener noreferrer">LinkedIn ↗</a>}{c.email?<a href={'mailto:'+c.email}>{c.email}</a>:<small>Correo no publicado</small>}{c.phones.map(p=><a href={'tel:'+p.number} key={p.number}>{p.number}</a>)}{c.email&&<small>{c.email_status==='verified'?'Correo verificado':c.email_status==='public_unverified'?'Correo publicado · sin verificar':'Correo sin verificar'}</small>}</td><td><span className={'stage-pill '+c.stage}>{stageLabels[c.stage]}</span><small>{c.owner||'Sin responsable'}</small>{c.last_interaction&&<small>Última: {formatDate(c.last_interaction)}</small>}{c.follow_up&&<small>Próxima: {formatDate(c.follow_up)}</small>}</td><td><div className="row-actions"><button title="Registrar llamada" aria-label={'Registrar llamada a '+c.name} onClick={()=>setDetail({contact:c,channel:'call'})}><Phone size={15}/></button><button title="Correo y ficha de contacto" aria-label={'Ver correo de '+c.name} onClick={()=>setDetail({contact:c,channel:'email'})}><Mail size={15}/></button><button title="Registrar mensaje" aria-label={'Registrar mensaje a '+c.name} onClick={()=>setDetail({contact:c,channel:'linkedin'})}><MessageSquare size={15}/></button><button title="Añadir comentario" aria-label={'Añadir comentario a '+c.name} onClick={()=>setDetail({contact:c,channel:'note'})}><FileText size={15}/></button><button title="Volver a buscar una vez" aria-label={'Volver a buscar a '+c.name} disabled={busy||activeRun(run)} onClick={()=>void rescan(c)}><RefreshCw size={15}/></button></div></td></tr>)}</tbody></table>{!rows.length&&<div className="compact-empty">{loading?'Cargando agenda…':'No hay contactos con estos filtros.'}</div>}</div>
    <p className="table-hint">Desliza la tabla para ver los canales, el seguimiento y las acciones.</p>
    <div className="alphabet" aria-label="Filtro alfabético"><button className={!filters.letter?'active':''} onClick={()=>set('letter','')}>Todas</button>{'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'.split('').map(l=><button key={l} className={filters.letter===l?'active':''} onClick={()=>set('letter',l)}>{l}</button>)}</div>
    <div className="pagination"><span>{total} contactos · {filters.sort==='opportunity'?'mayor oportunidad primero':'ordenados por nombre'}</span><div><button className="secondary small" disabled={page===1} onClick={()=>setPage(p=>p-1)}>Anterior</button><span>Página {page} de {Math.max(1,Math.ceil(total/50))}</span><button className="secondary small" disabled={page*50>=total} onClick={()=>setPage(p=>p+1)}>Siguiente</button></div></div>
    {detail&&<ContactHistory contact={detail.contact} initialChannel={detail.channel} onClose={()=>setDetail(null)} onRefresh={onRefresh} onReview={()=>{onReview(detail.contact);setDetail(null)}}/>}
  </section>
}

function ContactHistory({contact:initialContact,initialChannel,onClose,onRefresh,onReview}:{contact:CRMContact;initialChannel?:string;onClose:()=>void;onRefresh:()=>void;onReview:()=>void}) {
  const [c,setContact]=useState(initialContact),[tab,setTab]=useState<'info'|'register'|'history'>('info')
  const [events,setEvents]=useState<Interaction[]>([]),[scripts,setScripts]=useState<Script[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState(false),[editing,setEditing]=useState<Interaction|null>(null)
  const [optionsOpen,setOptionsOpen]=useState(false),[metadataOpen,setMetadataOpen]=useState(false),[saved,setSaved]=useState(false)
  const [form,setForm]=useState({author:c.owner||'Marco',channel:initialChannel||'note',result:initialChannel&&initialChannel!=='note'?'contacted':'',comment:'',occurred_at:'',follow_up:dateInput(c.follow_up),clear_follow_up:false,script_uuid:''})
  const [metadata,setMetadata]=useState({owner:c.owner,email:c.email||'',phone:c.phones[0]?.number||''})
  const set=(k:keyof typeof form,v:string|boolean)=>setForm(f=>({...f,[k]:v}))
  const load=useCallback(async()=>{const [history,templates,latest]=await Promise.all([api<Interaction[]>('/api/crm/contacts/'+c.id+'/interactions'),api<Script[]>('/api/scripts'),api<CRMContact>('/api/contacts/'+c.id)]);setEvents(history);setScripts(templates);setContact(latest)},[c.id])
  useEffect(()=>{void load().catch(e=>setError(message(e)));void api<SharedStatus>('/api/shared/status').then(s=>setForm(f=>({...f,author:s.actor}))).catch(()=>{})},[load])
  const corrected=new Set(events.map(e=>e.supersedes)),script=scripts.find(s=>s.uuid===form.script_uuid)
  const currentStage=[...events].filter(e=>!corrected.has(e.uuid)&&e.result).sort((a,b)=>a.occurred_at.localeCompare(b.occurred_at)||a.created_at.localeCompare(b.created_at)).at(-1)?.result||c.stage
  const hasScripts=scripts.some(s=>!s.archived||s.uuid===form.script_uuid)
  const renderedScript=(script?.text||'').replaceAll('{nombre}',c.name.split(' ')[0]).replaceAll('{gestora}',c.company)
  async function save(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');setSaved(false);try{
    const body={...form,result:form.result||null,occurred_at:dateValue(form.occurred_at),follow_up:dateValue(form.follow_up),script_uuid:form.script_uuid||null,script_version:editing?.script_uuid===form.script_uuid?editing?.script_version||undefined:undefined}
    await api('/api/crm/contacts/'+c.id+'/interactions'+(editing?'/'+editing.uuid:''),{method:editing?'PATCH':'POST',body:JSON.stringify(body)})
    await load();onRefresh();setSaved(true);setEditing(null);setForm(f=>({...f,comment:'',occurred_at:'',result:'',channel:'note'}))
  }catch(e){setError(message(e))}finally{setBusy(false)}}
  async function saveMetadata(){setBusy(true);setError('');try{await api('/api/crm/contacts/'+c.id,{method:'PATCH',body:JSON.stringify({...metadata,email:metadata.email||null,phone:metadata.phone||null})});await load();onRefresh()}catch(e){setError(message(e))}finally{setBusy(false)}}
  function correct(e:Interaction){setTab('register');setOptionsOpen(true);setSaved(false);setEditing(e);setForm({author:e.author,channel:e.channel,result:e.result||'',comment:e.comment,occurred_at:dateInput(e.occurred_at),follow_up:dateInput(e.follow_up),clear_follow_up:!!e.clear_follow_up,script_uuid:e.script_uuid||''})}
  return <Modal title={'Ficha de '+c.name} subtitle={(c.role||'Cargo por verificar')+' · '+c.company} onClose={onClose} wide>
    <div className="conversation-person"><Avatar contact={c}/><div><strong>{c.name}</strong><span>{c.company}</span></div><span className="stage-pill">{stageLabels[currentStage]}</span></div>
    <div className="tabs contact-detail-tabs" role="tablist" aria-label="Ficha del contacto">{[{id:'info',label:'Información'},{id:'register',label:'Registrar interacción'},{id:'history',label:'Historial'}].map(t=><button role="tab" aria-selected={tab===t.id} className={tab===t.id?'active':''} key={t.id} onClick={()=>setTab(t.id as typeof tab)}>{t.label}</button>)}</div>
    {tab==='info'&&<section className="contact-info-panel" aria-label="Información de contacto"><div className="contact-channel-grid"><article><strong>LinkedIn</strong>{c.linkedin_url?<a href={c.linkedin_url} target="_blank" rel="noopener noreferrer">Abrir perfil de {c.name} ↗</a>:<p>No se ha encontrado un perfil de LinkedIn.</p>}</article><article><strong>Correo</strong>{c.email?<><a href={'mailto:'+c.email}>{c.email}</a><small>{c.email_status==='verified'?'Verificado':'Publicado o aportado · entrega sin verificar'}</small></>:<p>No se ha encontrado un correo publicado.</p>}</article><article><strong>Teléfono</strong>{c.phones.length?c.phones.map(p=><div key={p.number}><a href={'tel:'+p.number}>{p.number}</a><small>{p.type==='public'?'Publicado en una fuente pública':p.type==='manual'?'Aportado manualmente':'Fuente externa'}</small></div>):<p>No se ha encontrado un teléfono publicado.</p>}</article></div><p className="hint">{c.linkedin_url?'Perfil localizado en LinkedIn.':'Identificado en fuentes web; LinkedIn pendiente.'} {c.photo_url?'Foto: '+(c.photo_origin||'fuente pública')+'.':'Foto no disponible; se muestran iniciales.'}</p>{!!c.email_candidates?.length&&<div className="notice"><span>Otros correos encontrados: {c.email_candidates.join(', ')}. Se ha conservado el correo guardado; revisa las fuentes antes de sustituirlo.</span></div>}<div className="inline-actions"><button className="primary small" onClick={()=>setTab('register')}><Plus size={15}/>Registrar {initialChannel==='call'?'llamada':initialChannel==='email'?'correo':'interacción'}</button><button className="secondary small" onClick={onReview}>Revisar datos y fuentes</button></div>{(c.contact_sources?.length||c.evidence.length)>0&&<details className="settings-extra"><summary>Fuentes de los datos</summary>{[...(c.contact_sources||[]),...c.evidence.filter(e=>['email','phone','photo_url','linkedin_url','name','role'].includes(e.field))].filter((e,i,a)=>a.findIndex(v=>v.field===e.field&&v.url===e.url&&v.quote===e.quote)===i).map((e,i)=><div className="contact-source" key={i}><strong>{e.field==='email'?'Correo':e.field==='phone'?'Teléfono':e.field==='photo_url'?'Foto':e.field==='linkedin_url'?'LinkedIn':e.field==='role'?'Cargo':'Identidad'}</strong>{e.url?<a href={e.url} target="_blank" rel="noopener noreferrer">Abrir fuente ↗</a>:<span>Revisión manual</span>}<small>{formatDate(e.observed_at)}</small></div>)}</details>}</section>}
    {tab==='info'&&<QualificationPanel contact={c} onSaved={updated=>{setContact(updated);onRefresh()}}/>}
    {tab==='info'&&<ContactSignals signals={c.business_signals}/>}
    {tab==='register'&&    <form className="quick-conversation" onSubmit={event=>void save(event)}><div className="section-line"><h3>{editing?'Corregir registro':'¿Cómo ha ido?'}</h3><div className="channel-switch" aria-label="Tipo de interacción">{Object.entries(channelLabels).map(([key,label])=><button type="button" key={key} aria-pressed={form.channel===key} onClick={()=>{set('channel',key);set('result',key==='note'?'':'contacted');setSaved(false)}}>{key==='call'?<Phone size={14}/>:key==='note'?<FileText size={14}/>:key==='email'?<Mail size={14}/>:<MessageSquare size={14}/>}<span>{label}</span></button>)}</div></div>
      <div className={"quick-fields "+(!hasScripts?"single":"")}><label>Resultado<select value={form.result} onChange={e=>set('result',e.target.value)}><option value="">Mantener etapa actual</option>{Object.entries(stageLabels).filter(([key])=>key!=='pending').map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label>{hasScripts&&<label><span>Guion utilizado <small className="optional-label">opcional</small></span><select value={form.script_uuid} onChange={e=>set('script_uuid',e.target.value)}><option value="">Sin guion</option>{scripts.filter(s=>!s.archived||s.uuid===form.script_uuid).map(s=><option key={s.uuid} value={s.uuid}>{s.title} · v{s.versions.at(-1)?.version}</option>)}</select></label>}</div>
      {script&&<div className="script-preview"><p>{renderedScript}</p><button className="text-button" type="button" onClick={()=>void navigator.clipboard.writeText(renderedScript).catch(e=>setError(message(e)))}><Copy size={14}/>Copiar apertura</button></div>}
      <label className="conversation-note">Una nota sobre la conversación<textarea aria-label="Comentario de interacción" rows={4} value={form.comment} maxLength={10000} onChange={e=>{set('comment',e.target.value);setSaved(false)}} placeholder="Qué te ha dicho, qué le interesa o qué harías diferente…"/></label>
      <button className="text-button optional-toggle" type="button" aria-expanded={optionsOpen} aria-controls="conversation-extra" onClick={()=>setOptionsOpen(v=>!v)}><Plus size={14}/>Seguimiento y otros detalles<ChevronDown size={14}/></button>
      {optionsOpen&&<div className="conversation-extra" id="conversation-extra"><div className="form-grid"><label>Próximo seguimiento<input type="datetime-local" disabled={form.clear_follow_up} value={form.follow_up} onChange={e=>set('follow_up',e.target.value)}/></label><label>Responsable<input required maxLength={100} value={form.author} onChange={e=>set('author',e.target.value)}/></label><label>Fecha de interacción<input type="datetime-local" value={form.occurred_at} onChange={e=>set('occurred_at',e.target.value)}/><small>Si la dejas vacía, se guarda la fecha actual.</small></label><label className="checkbox-label"><input type="checkbox" checked={form.clear_follow_up} onChange={e=>set('clear_follow_up',e.target.checked)}/>Cerrar seguimiento pendiente</label></div></div>}
      <ErrorBox error={error}/><div className="conversation-actions"><small>{editing?'La corrección conservará el registro anterior.':'Fecha y responsable se guardan automáticamente.'}</small>{editing&&<button type="button" className="secondary small" onClick={()=>{setEditing(null);setForm(f=>({...f,comment:'',occurred_at:''}))}}>Cancelar corrección</button>}<button className="primary" disabled={busy}><Busy busy={busy}/><Check size={16}/>Guardar interacción</button></div>{saved&&<p className="save-confirmation" role="status"><Check size={14}/>Guardado en el historial.</p>}
    </form>}
    {tab==='history'&&<section className="conversation-history"><div className="section-line"><h3>Historial comercial <span>{events.length}</span></h3><button className="text-button" onClick={onReview}><Settings2 size={14}/>Revisar calificación y fuentes</button></div><div className="timeline">{!events.length&&<p className="hint">Todavía no hay conversaciones guardadas.</p>}{[...events].reverse().map(e=><article key={e.uuid} className={corrected.has(e.uuid)?'superseded':''}><div><strong>{channelLabels[e.channel]}{e.result?' · '+stageLabels[e.result]:''}</strong><time>{formatDate(e.occurred_at)}</time></div><small>{e.author}{e.script_uuid?' · '+(scripts.find(s=>s.uuid===e.script_uuid)?.title||'Guion')+' · v'+e.script_version:''}{e.supersedes?' · Corrección':''}{corrected.has(e.uuid)?' · Registro corregido':''}</small><p>{e.comment||'Sin comentario'}</p>{e.follow_up&&<small>Seguimiento: {formatDate(e.follow_up)}</small>}{!corrected.has(e.uuid)&&<button className="text-button" onClick={()=>correct(e)}>Corregir registro</button>}</article>)}</div></section>}
    {tab==='info'&&<section className="contact-settings"><button className="text-button optional-toggle" aria-expanded={metadataOpen} onClick={()=>setMetadataOpen(v=>!v)}><Settings2 size={14}/>Editar datos de contacto<ChevronDown size={14}/></button>{metadataOpen&&<div className="form-grid"><label>Responsable habitual<input value={metadata.owner} onChange={e=>setMetadata(m=>({...m,owner:e.target.value}))}/></label><label>Correo profesional<input type="email" value={metadata.email} onChange={e=>setMetadata(m=>({...m,email:e.target.value}))}/></label><label>Teléfono principal<input value={metadata.phone} onChange={e=>setMetadata(m=>({...m,phone:e.target.value}))}/></label><div className="inline-actions"><button className="secondary small" disabled={busy} onClick={()=>void saveMetadata()}>Guardar datos de contacto</button></div></div>}</section>}
  </Modal>
}

const qualificationQuestions:{key:'change'|'timing'|'decision';label:string;hint:string}[]=[
  {key:'change',label:'P3 · ¿Han probado o incorporado alguna herramienta en el último año?',hint:'La que más pesa: si no cambian nada desde hace años, no es nuestro cliente.'},
  {key:'timing',label:'P4 · ¿Tienen un motivo para actuar este año?',hint:'Fondo nuevo, más compañías que cubrir, contrataciones o un nuevo responsable.'},
  {key:'decision',label:'P6 · ¿Decide esta persona o alguien cercano, con presupuesto?',hint:'Responde «No» si decide la matriz, un grupo o IT central, o si no hay presupuesto.'}]

function QualificationPanel({contact:c,onSaved}:{contact:CRMContact;onSaved:(c:CRMContact)=>void}) {
  const [busy,setBusy]=useState(false),[error,setError]=useState('')
  const answers=c.qualification||{change:null,timing:null,decision:null}
  async function answer(key:string,value:Answer){setBusy(true);setError('');try{onSaved(await api<CRMContact>('/api/crm/contacts/'+c.id+'/qualification',{method:'PUT',body:JSON.stringify({change:answers.change,timing:answers.timing,decision:answers.decision,[key]:value})}))}catch(e){setError(message(e))}finally{setBusy(false)}}
  return <section className="qualification-panel" aria-label="Oportunidad comercial">
    <div className="section-line"><h3>Oportunidad comercial</h3><strong className={'opportunity-pill '+c.opportunity_status}>{c.opportunity_score}/100 · {opportunityLabels[c.opportunity_status]}</strong></div>
    <p className="hint">Marca lo que respondió en la llamada de cualificación. Las señales sin revisar cuentan la mitad. El encaje ({c.score}/100) no cambia.</p>
    {qualificationQuestions.map(q=><div className="qualification-question" key={q.key}><div><strong>{q.label}</strong><small>{q.hint}</small></div><div className="channel-switch answer-switch" role="group" aria-label={q.label}>{([['yes','Sí'],['no','No'],[null,'Sin saber']] as [Answer,string][]).map(([value,label])=><button type="button" key={label} aria-pressed={(answers[q.key]??null)===value} disabled={busy} onClick={()=>void answer(q.key,value)}>{label}</button>)}</div></div>)}
    <ul className="opportunity-reasons">{c.opportunity_reasons.map(r=><li key={r.field}><span>{r.label}</span><b>{r.points}/{r.maximum}</b></li>)}</ul>
    <ErrorBox error={error}/>
  </section>
}

export function ScriptsWorkspace({revision,onRefresh}:{revision:number;onRefresh:()=>void}) {
  const [scripts,setScripts]=useState<Script[]>([]),[stats,setStats]=useState<ScriptStat[]>([]),[error,setError]=useState(''),[showArchived,setShowArchived]=useState(false)
  const [editing,setEditing]=useState<Script|null|undefined>(undefined),[form,setForm]=useState({title:'',channel:'linkedin',text:'',archived:false}),[busy,setBusy]=useState(false)
  useEffect(()=>{let alive=true;void Promise.all([api<Script[]>('/api/scripts'),api<ScriptStat[]>('/api/scripts-statistics')]).then(([s,t])=>{if(alive){setScripts(s);setStats(t);setError('')}}).catch(e=>{if(alive)setError(message(e))});return()=>{alive=false}},[revision])
  function open(s:Script|null,duplicate=false){setEditing(duplicate?null:s);setForm({title:s?(s.title+(duplicate?' · copia':'')):'',channel:s?.channel||'linkedin',text:s?.text||'',archived:duplicate?false:s?.archived||false})}
  async function save(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await api('/api/scripts'+(editing?'/'+editing.uuid:''),{method:editing?'PATCH':'POST',body:JSON.stringify(form)});onRefresh();setEditing(undefined)}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function archive(s:Script){setError('');try{await api('/api/scripts/'+s.uuid,{method:'PATCH',body:JSON.stringify({title:s.title,channel:s.channel,text:s.text,archived:!s.archived})});onRefresh()}catch(e){setError(message(e))}}
  return <section><div className="results-heading"><div><h2>Guiones que abren conversaciones</h2><p>Compara resultados por versión y canal. El éxito principal es una demo o reunión.</p></div><button className="primary small" onClick={()=>open(null)}><Plus size={16}/>Nuevo guion</button></div><ErrorBox error={error}/><label className="checkbox-label"><input type="checkbox" checked={showArchived} onChange={e=>setShowArchived(e.target.checked)}/>Mostrar archivados</label>
    <div className="scripts-grid">{scripts.filter(s=>showArchived||!s.archived).map(s=><article className="panel script-card" key={s.uuid}><div className="section-line"><span className="stage-pill">{channelLabels[s.channel]}</span><small>v{s.versions.at(-1)?.version}{s.archived?' · Archivado':''}</small></div><h3>{s.title}</h3><p>{s.text}</p><div className="inline-actions"><button className="secondary small" onClick={()=>open(s)}>Editar</button><button className="text-button" onClick={()=>open(s,true)}><Copy size={14}/>Duplicar</button><button className="text-button" onClick={()=>void archive(s)}>{s.archived?'Restaurar':'Archivar'}</button></div></article>)}</div>{!scripts.length&&<div className="panel compact-empty">Crea un guion para llamadas, LinkedIn o correo. Después selecciónalo al registrar una interacción.</div>}
    <div className="results-heading"><div><h2>Resultados por guion</h2><p>Personas únicas. La demo se atribuye al último guion usado antes de conseguirla.</p></div></div><div className="table-scroll panel"><table><thead><tr><th>Guion / versión</th><th>Canal</th><th>Contactados</th><th>Respuestas</th><th>Interesados</th><th>Rechazos</th><th>Demos</th><th>Conversión</th></tr></thead><tbody>{stats.map(s=><tr key={s.script_uuid+':'+s.version+':'+s.channel}><td>{s.title}<small>Versión {s.version}</small></td><td>{channelLabels[s.channel]}</td><td>{s.approached}</td><td>{s.responses}</td><td>{s.interested}</td><td>{s.rejected}</td><td>{s.demos}</td><td><b>{s.conversion}%</b></td></tr>)}</tbody></table>{!stats.length&&<div className="compact-empty">Todavía no hay estadísticas.</div>}</div>
    {editing!==undefined&&<Modal title={editing?'Editar guion':'Nuevo guion'} subtitle="Cada cambio de texto crea una versión; los resultados anteriores se conservan." onClose={()=>setEditing(undefined)} wide><form onSubmit={e=>void save(e)}><div className="form-grid"><label>Título<input required minLength={2} maxLength={150} value={form.title} onChange={e=>setForm(f=>({...f,title:e.target.value}))}/></label><label>Canal<select value={form.channel} onChange={e=>setForm(f=>({...f,channel:e.target.value}))}>{['call','linkedin','email'].map(k=><option key={k} value={k}>{channelLabels[k]}</option>)}</select></label><label className="full">Texto del guion<textarea required rows={7} maxLength={20000} value={form.text} onChange={e=>setForm(f=>({...f,text:e.target.value}))} placeholder="Hola {nombre}, te escribo por vuestro trabajo en {gestora}…"/></label><p className="hint full">Variables disponibles: {'{nombre}'} y {'{gestora}'}. Se rellenan desde la ficha del contacto.</p><div className="script-preview full"><strong>Vista previa</strong><p>{form.text.replaceAll('{nombre}','Ana').replaceAll('{gestora}','Gestora de ejemplo')}</p><button type="button" className="text-button" onClick={()=>void navigator.clipboard.writeText(form.text).catch(e=>setError(message(e)))}><Copy size={14}/>Copiar plantilla</button></div></div><ErrorBox error={error}/><div className="modal-actions"><button type="button" className="secondary" onClick={()=>setEditing(undefined)}>Cancelar</button><button className="primary" disabled={busy}><Busy busy={busy}/>Guardar guion</button></div></form></Modal>}
  </section>
}

type ApolloConnectionStatus={configured:boolean;free_budget:number;free_account:boolean;pending:number;access?:{status:string;message:string;checked_at?:string};saved_access?:{status:string;message:string;checked_at?:string}}
function apolloAccessLabel(status:ApolloConnectionStatus){return !status.configured?'Sin conectar':status.access?.status==='verified'?'Acceso verificado':['denied','invalid'].includes(status.access?.status||'')?'Sin acceso':'Clave guardada'}
function canSearchApollo(status:ApolloConnectionStatus){return status.configured&&!['denied','invalid'].includes(status.access?.status||'')}
function ApolloConnection({onConfigured,source='people'}:{onConfigured:(ready:boolean)=>void;source?:'people'|'saved_contacts'}){
  const [editingKey,setEditingKey]=useState(false)
  const [status,setStatus]=useState<ApolloConnectionStatus|null>(null),[key,setKey]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('')
  useEffect(()=>{let alive=true;void api<ApolloConnectionStatus>('/api/settings/apollo').then(s=>{if(alive){setStatus(s);onConfigured(canSearchApollo(source==='saved_contacts'?{...s,access:s.saved_access}:s))}}).catch(e=>{if(alive)setError(message(e))});return()=>{alive=false}},[onConfigured,source])
  async function check(){setBusy(true);setError('');try{const s=await api<ApolloConnectionStatus>('/api/apollo/connection-check'+(source==='saved_contacts'?'?source=saved_contacts':''),post({}));setStatus(s);setEditingKey(false);onConfigured(canSearchApollo(source==='saved_contacts'?{...s,access:s.saved_access}:s))}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function connect(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');try{await api<ApolloConnectionStatus>('/api/settings/apollo',post({api_key:key.trim(),free_budget:status?.free_budget||0,free_account:status?.free_account||false}));setKey('');const s=await api<ApolloConnectionStatus>('/api/apollo/connection-check'+(source==='saved_contacts'?'?source=saved_contacts':''),post({}));setStatus(s);onConfigured(canSearchApollo(source==='saved_contacts'?{...s,access:s.saved_access}:s))}catch(e){setError(message(e))}finally{setBusy(false)}}
  const shown=status&&(source==='saved_contacts'?{...status,access:status.saved_access}:status)
  return <section className="connection-panel apollo-connection" aria-label="Conexión de Apollo"><div className="connection-heading"><Settings2 size={18}/><div><strong>{status?.configured?'Apollo · '+apolloAccessLabel(shown!):'Conecta Apollo para empezar'}</strong><p>La búsqueda consume 0 créditos. El acceso a la API depende de tu cuenta.</p></div><a href="https://app.apollo.io/#/settings/integrations/api" target="_blank" rel="noopener noreferrer">Obtener API key ↗</a></div>{status?.configured&&<><p className="hint" role="status">{shown?.access?.message||'La clave está guardada. Comprueba si tu cuenta permite la búsqueda gratuita por API.'}</p><button className="secondary small" disabled={busy} onClick={()=>void check()}><Busy busy={busy}/>{busy?'Comprobando…':'Comprobar acceso gratuito'}</button><button className="text-button" disabled={busy} onClick={()=>setEditingKey(v=>!v)}>{editingKey?'Cancelar cambio de clave':'Actualizar clave'}</button></>}{(!status?.configured||editingKey)&&<><form onSubmit={event=>void connect(event)}><label>API key de Apollo<input type="password" autoComplete="off" spellCheck={false} maxLength={512} value={key} onChange={e=>setKey(e.target.value)} placeholder="Pega tu clave de Apollo"/></label><button className="primary" disabled={busy||!key.trim()}><Busy busy={busy}/>{busy?'Comprobando…':'Guardar clave'}</button></form><p className="hint">Se guarda solo en este equipo. Al guardar comprobamos el acceso con una búsqueda de 0 créditos, sin pedir correos ni teléfonos.</p></>}<details className="settings-extra"><summary>Resolver acceso gratuito</summary><p>Apollo exige correo de empresa para las cuentas Free que usan la búsqueda API. Comprueba tu correo en Apollo → Settings → Profile → General. Si es personal, puedes cambiarlo por tu correo de empresa y confirmar el correo de verificación. Después pulsa Comprobar acceso gratuito.</p><p>Si ya utilizas correo de empresa y sigue bloqueado, Apollo debe revisar la elegibilidad de tu cuenta.</p><a href="https://docs.apollo.io/reference/people-api-search" target="_blank" rel="noopener noreferrer">Requisitos oficiales ↗</a></details><ErrorBox error={error}/></section>
}
export function ScreenerWorkspace({contacts,health,run,revision,onRefresh,onRun,onAgenda}:{contacts:Contact[];health:Health|null;run:Run|null;revision:number;onRefresh:()=>void;onRun:(r:Run)=>void;onAgenda:()=>void}) {
  const [apolloReady,setApolloReady]=useState(false)
  const [source,setSource]=useState<'people'|'saved_contacts'>('people')
  const [mode,setMode]=useState('discover'),[continuous,setContinuous]=useState(true),[form,setForm]=useState({keywords:'equity asset management\nrenta variable\nboutique asset manager',country:'España',titles:'Chief Investment Officer\nHead of Equities\nInvestment Director',domains:'',employees_min:'5',employees_max:'200',page:'1'})
  const [discovery,setDiscovery]=useState<ScoutRun|null>(null),[selected,setSelected]=useState<string[]>([]),[error,setError]=useState(''),[busy,setBusy]=useState(false),[csvOpen,setCSVOpen]=useState(false)
  useEffect(()=>{let alive=true;void api<ScoutRun[]>('/api/search-history').then(history=>{if(alive)setDiscovery(history.find(r=>r.provider==='apollo'&&r.mode==='discover')||null)}).catch(e=>{if(alive)setError(message(e))});return()=>{alive=false}},[revision])
  async function search(){setBusy(true);setError('');setSelected([]);try{
    const result=await api<ScoutRun>('/api/apollo/searches',post({...form,source,continuous,countries:form.country?[form.country]:health?.countries||[],titles:form.titles.split('\n').map(t=>t.trim()).filter(Boolean),domains:form.domains.split(/[\s,;]+/).filter(Boolean),employees_min:Number(form.employees_min),employees_max:Number(form.employees_max),page:Number(form.page)}));if(result.provider==='apollo')setDiscovery(result);onRun(result)
  }catch(e){setError(message(e))}finally{setBusy(false)}}
  async function accept(){if(!discovery)return;setBusy(true);setError('');try{onRun(await api<Run>('/api/apollo/candidates/accept',post({run_id:discovery.id,candidate_ids:selected,enrich:true})));setSelected([])}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function recover(){setBusy(true);setError('');try{onRun(await api<Run>('/api/apollo/pending/resume',post({})))}catch(e){setError(message(e))}finally{setBusy(false)}}
  const candidates=discovery?.candidates||[],partial=candidates.filter(c=>selected.includes(c.id)&&c.partial).length
  return <section><div className="results-heading"><div><h2>Screener complementario</h2><p>Descubre personas con Apollo o completa perfiles que ya están en tu agenda.</p></div><div className="inline-actions"><button className="secondary small" disabled={busy||activeRun(run)} onClick={()=>void recover()}><RefreshCw size={14}/>Recuperar teléfonos pendientes</button><button className="secondary small" onClick={()=>setCSVOpen(true)}><ArrowDownToLine size={14}/>Importar CSV</button></div></div>
    <div className="tabs"><button className={mode==='discover'?'active':''} onClick={()=>setMode('discover')}>Descubrir personas</button><button className={mode==='enrich'?'active':''} onClick={()=>setMode('enrich')}>Completar contactos existentes</button></div><ErrorBox error={error}/>
    {mode==='discover'?<><label className="apollo-source">Origen de Apollo<select aria-label="Origen de Apollo" value={source} onChange={e=>{setSource(e.target.value as 'people'|'saved_contacts');setApolloReady(false);setForm(f=>({...f,keywords:'',page:'1'}))}}><option value="people">Descubrir personas nuevas</option><option value="saved_contacts">Sincronizar contactos guardados · 0 créditos</option></select></label>{source==='saved_contacts'&&<div className="notice"><Users size={17}/><span>Lee los contactos que ya has guardado en Apollo y los incorpora a tu agenda. No descubre personas nuevas. Sin enriquecimiento ni coste por créditos. La lista se vuelve a comprobar cada cinco minutos.</span><a href="https://app.apollo.io/#/people" target="_blank" rel="noopener noreferrer">Abrir Apollo ↗</a></div>}<ApolloConnection source={source} onConfigured={setApolloReady}/><div className="panel screener-form"><div className="form-grid"><label>Palabras clave<textarea aria-label="Palabras clave de Apollo" rows={3} maxLength={6000} value={form.keywords} onChange={e=>setForm(f=>({...f,keywords:e.target.value}))} placeholder={'renta variable\nequity\nboutique asset manager'}/><small>Una palabra o frase por línea, o separadas por comas. Buscamos cada una y unimos los resultados sin duplicados. Máximo 20.</small></label>{source==='people'&&<><label>País de la gestora<select value={form.country} onChange={e=>setForm(f=>({...f,country:e.target.value}))}><option value="">Toda Europa</option>{health?.countries.map(c=><option key={c}>{c}</option>)}</select></label><label>Cargos · uno por línea<textarea rows={3} value={form.titles} onChange={e=>setForm(f=>({...f,titles:e.target.value}))}/></label><label>Dominios de gestoras · opcional<textarea rows={3} value={form.domains} onChange={e=>setForm(f=>({...f,domains:e.target.value}))} placeholder="gestora.com, otra-gestora.com"/><button className="text-button" onClick={()=>setForm(f=>({...f,domains:Array.from(new Set(contacts.map(c=>(c as Contact&{domain?:string}).domain).filter(Boolean))).join('\n')}))}>Usar gestoras conocidas</button></label><label>Empleados mínimo<input type="number" min={1} max={200} value={form.employees_min} onChange={e=>setForm(f=>({...f,employees_min:e.target.value}))}/></label><label>Empleados máximo<input type="number" min={1} max={200} value={form.employees_max} onChange={e=>setForm(f=>({...f,employees_max:e.target.value}))}/></label></>}<label>Página de resultados<input type="number" min={1} max={500} value={form.page} onChange={e=>setForm(f=>({...f,page:e.target.value}))}/></label><div className="inline-actions"><button className="primary small" disabled={busy||!apolloReady||(activeRun(run)&&!continuous)} onClick={()=>void search()}><Busy busy={busy}/><Search size={15}/>{source==='saved_contacts'?'Sincronizar contactos de Apollo':'Buscar en Apollo'}</button></div></div><label className="checkbox-label"><input type="checkbox" checked={continuous} onChange={e=>setContinuous(e.target.checked)}/>Buscar continuamente, avanzando por páginas</label><p className="hint">Los perfiles completos se incorporan automáticamente durante el escaneo continuo a tu lista principal. Los nombres ocultos quedan pendientes; no se enriquecen automáticamente.</p><p className="hint">Búsqueda de personas: 0 créditos. Completar nombres, correos y teléfonos puede consumir cuota gratuita. Los ya contactados se omiten.</p></div>
      {candidates.length>0&&<section className="apollo-results">      <div className="results-heading"><div><h2>Candidatos encontrados</h2><p>{candidates.length} candidatos · {discovery?.omitted||0} contactados omitidos{discovery?' · Búsqueda #'+discovery.id:''}</p></div><button className="primary small" disabled={!selected.length||busy||activeRun(run)} onClick={()=>void accept()}>Incorporar {selected.length||''} seleccionados</button></div>{partial>0&&<div className="notice"><Mail size={16}/><span>{partial} perfiles tienen apellido oculto o incompleto. Incorporarlos requiere completar su perfil, hasta {partial} créditos gratuitos. Sin saldo verificable se bloqueará la operación.</span></div>}
      <div className="table-scroll panel"><table><thead><tr><th><input type="checkbox" aria-label="Seleccionar candidatos" checked={candidates.length>0&&selected.length===candidates.length} onChange={e=>setSelected(e.target.checked?candidates.map(c=>c.id):[])}/></th><th>Nombre</th><th>Cargo</th><th>Gestora</th><th>País</th><th>Estado</th></tr></thead><tbody>{candidates.map(c=><tr key={c.id}><td><input type="checkbox" aria-label={'Seleccionar candidato '+c.name} checked={selected.includes(c.id)} onChange={e=>setSelected(s=>e.target.checked?[...s,c.id]:s.filter(id=>id!==c.id))}/></td><td>{c.linkedin_url?<a href={c.linkedin_url} target="_blank" rel="noopener noreferrer">{c.name} ↗</a>:c.name}</td><td>{c.role}</td><td>{c.company}</td><td>{c.country||'Por verificar'}</td><td><small>{c.partial?'Perfil incompleto':c.existing_id?'Ya en agenda':'Nuevo candidato'}</small></td></tr>)}</tbody></table>{!candidates.length&&<div className="compact-empty">{activeRun(discovery)?'Buscando candidatos…':'Prepara los filtros e inicia una búsqueda.'}</div>}</div></section>}{!candidates.length&&discovery&&<div className="apollo-search-status" role="status">{activeRun(discovery)?<><Busy busy={true}/>Apollo está buscando personas…</>:discovery.status==='failed'||discovery.status==='quota_exhausted'?<span>{discovery.errors[discovery.errors.length-1]||'La búsqueda se ha detenido. Revisa la conexión de Apollo.'}</span>:<span>{discovery.status==='completed'?'Esta búsqueda de Apollo no dejó perfiles para revisar. Los contactos incorporados están en tu agenda.':'Búsqueda detenida. Los resultados guardados siguen en Contactos.'}</span>}</div>}</>:<div className="panel"><h3>Completa desde la lista unificada</h3><p className="hint">Selecciona personas en la agenda principal y pulsa Completar correo o Completar teléfono. Los ya contactados permanecen protegidos.</p><button className="secondary" onClick={onAgenda}>Ir a la lista unificada<ArrowRight size={15}/></button></div>}
    {csvOpen&&<CSVDialog onClose={()=>setCSVOpen(false)} onRefresh={onRefresh}/>}</section>
}

function CSVDialog({onClose,onRefresh}:{onClose:()=>void;onRefresh:()=>void}) {
  const [text,setText]=useState(''),[preview,setPreview]=useState<{columns:string[];rows:Record<string,string>[];count:number}|null>(null),[mapping,setMapping]=useState<Record<string,string>>({}),[result,setResult]=useState<{new:number;duplicates:number;omitted:number;errors:string[]}|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false)
  const fields:{key:string;label:string;aliases:string[]}[]=[{key:'name',label:'Nombre completo',aliases:['name','nombre','full name']},{key:'first_name',label:'Nombre',aliases:['first name','first_name']},{key:'last_name',label:'Apellidos',aliases:['last name','last_name']},{key:'company',label:'Gestora',aliases:['company','company name','gestora','empresa']},{key:'role',label:'Cargo',aliases:['title','job title','cargo']},{key:'country',label:'País',aliases:['country','company country','país']},{key:'employees',label:'Empleados',aliases:['# employees','employees','empleados']},{key:'domain',label:'Dominio',aliases:['website','company website','domain']},{key:'linkedin_url',label:'LinkedIn',aliases:['person linkedin url','linkedin url','linkedin']},{key:'email',label:'Correo',aliases:['email','correo']},{key:'phone',label:'Teléfono',aliases:['mobile phone','work direct phone','phone','teléfono']},{key:'photo_url',label:'URL de foto',aliases:['photo url','photo_url','foto']}]
  async function prepare(value=text){setBusy(true);setError('');setResult(null);try{const p=await api<typeof preview>('/api/imports/csv/preview',post({text:value}));setPreview(p);setMapping(Object.fromEntries(fields.map(f=>[f.key,p?.columns.find(h=>f.aliases.includes(h.toLowerCase().trim()))||''])))}catch(e){setError(message(e))}finally{setBusy(false)}}
  async function importData(){setBusy(true);setError('');try{setResult(await api('/api/imports/csv',post({text,mapping})));onRefresh()}catch(e){setError(message(e))}finally{setBusy(false)}}
  return <Modal title="Importar contactos desde CSV" subtitle="Revisa columnas y ejemplos antes de guardar. Las conversaciones existentes se conservan." onClose={onClose} wide><label>Archivo CSV<input type="file" accept=".csv,.tsv,text/csv" onChange={e=>{const file=e.target.files?.[0];if(file){if(file.size>3000000){setError('El archivo supera 3 MB.');return}void file.text().then(t=>{setText(t);void prepare(t)}).catch(e=>setError(message(e)))}}}/></label><label>O pega el contenido<textarea rows={3} value={text} onChange={e=>{setText(e.target.value);setPreview(null);setResult(null)}}/></label><button className="secondary small" disabled={busy||!text} onClick={()=>void prepare()}><Busy busy={busy}/>Previsualizar CSV</button><ErrorBox error={error}/>{preview&&<><p className="hint">{preview.count} filas · los teléfonos y correos importados se marcarán sin verificar.</p><div className="form-grid">{fields.map(f=><label key={f.key}>{f.label}<select value={mapping[f.key]||''} onChange={e=>setMapping(m=>({...m,[f.key]:e.target.value}))}><option value="">No importar</option>{preview.columns.map(c=><option key={c}>{c}</option>)}</select></label>)}</div><div className="table-scroll preview-table"><table><thead><tr>{preview.columns.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{preview.rows.map((r,i)=><tr key={i}>{preview.columns.map(h=><td key={h}>{r[h]}</td>)}</tr>)}</tbody></table></div></>}{result&&<div className="notice"><Check size={18}/><div>{result.new} nuevos · {result.duplicates} coincidencias actualizadas · {result.omitted} ya contactados omitidos{result.errors.map((e,i)=><p key={i}>{e}</p>)}</div></div>}<div className="modal-actions"><button className="secondary" onClick={onClose}>Cerrar</button><button className="primary" disabled={busy||!preview||!!result||(!mapping.name&&(!mapping.first_name||!mapping.last_name))||!mapping.company} onClick={()=>void importData()}>Guardar contactos</button></div></Modal>
}

export function IntegrationSettings({running,onRefresh,tavily,tavilyConfigured=false,apolloRunning=false}:{running:boolean;onRefresh:()=>void;tavily?:React.ReactNode;tavilyConfigured?:boolean;apolloRunning?:boolean}) {
  const [tab,setTab]=useState('connections')
  const [apollo,setApollo]=useState<ApolloConnectionStatus>({configured:false,free_budget:0,free_account:false,pending:0}),[key,setKey]=useState(''),[localModel,setLocalModel]=useState<LocalModelStatus|null>(null),[shared,setShared]=useState<SharedStatus|null>(null),[actor,setActor]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[balance,setBalance]=useState<unknown>(null)
  const load=useCallback(async()=>{
    const results=await Promise.allSettled([api<typeof apollo>('/api/settings/apollo'),api<LocalModelStatus>('/api/local-model'),api<SharedStatus>('/api/shared/status')])
    if(results[0].status==='fulfilled')setApollo(results[0].value)
    if(results[1].status==='fulfilled')setLocalModel(results[1].value)
    if(results[2].status==='fulfilled'){setShared(results[2].value);setActor(results[2].value.actor)}
    const failure=results.find(r=>r.status==='rejected');if(failure?.status==='rejected')throw failure.reason
  },[])
  useEffect(()=>{void load().catch(e=>setError(message(e)))},[load])
  async function action(callback:()=>Promise<unknown>,success:string){setBusy(true);setError('');setNotice('');try{await callback();await load();onRefresh();setNotice(success)}catch(e){setError(message(e))}finally{setBusy(false)}}
  return <div className="integration-settings settings-page">
    <div className="settings-tabs" role="tablist" aria-label="Apartados de ajustes">{[{id:'connections',label:'Conexiones',icon:Settings2},{id:'profile',label:'Mi perfil',icon:Users},{id:'data',label:'Datos e historial',icon:FileText},{id:'model',label:'Modelo local',icon:LoaderCircle}].map(t=><button key={t.id} role="tab" aria-selected={tab===t.id} aria-controls={'settings-'+t.id} id={'settings-tab-'+t.id} onClick={()=>{setTab(t.id);setNotice('');setError('')}}><t.icon size={16}/>{t.label}</button>)}</div>
    <ErrorBox error={error}/>{notice&&<div className="notice settings-feedback" role="status"><Check size={16}/>{notice}</div>}
    <div role="tabpanel" id={'settings-'+tab} aria-labelledby={'settings-tab-'+tab} className="settings-content">
    {tab==='connections'&&<><div className="settings-section-heading"><h2>Conecta tus fuentes</h2><p>Guarda cada clave una vez. Queda disponible para tus búsquedas.</p></div><div className="settings-grid">
      {tavily&&<section className="settings-card"><div className="settings-card-heading"><div className="settings-provider-icon"><Search size={20}/></div><div><h3>Tavily</h3><p>Gestoras y decisores en la web</p></div><span className={'settings-pill '+(tavilyConfigured?'ready':'')}>{tavilyConfigured?'Conectado':'Sin conectar'}</span></div>{tavily}</section>}
      <section className="settings-card"><div className="settings-card-heading"><div className="settings-provider-icon"><Users size={20}/></div><div><h3>Apollo</h3><p>Personas por cargo y compañía</p></div><span className={'settings-pill '+(apollo.access?.status==='verified'?'ready':'')}>{apolloAccessLabel(apollo)}</span></div><p className="settings-description">Las búsquedas usan cero créditos, pero tu cuenta debe tener acceso a esta API.</p><label>API key de Apollo<input type="password" autoComplete="off" spellCheck={false} value={key} maxLength={512} placeholder={apollo.configured?'Pega una nueva clave para sustituirla':'Pega tu clave de Apollo'} onChange={e=>setKey(e.target.value)}/></label><div className="settings-card-actions"><button className="primary small" disabled={busy||apolloRunning||(!apollo.configured&&!key.trim())} onClick={()=>void action(async()=>{await api('/api/settings/apollo',post({...(key.trim()?{api_key:key.trim()}:{}),free_budget:apollo.free_budget,free_account:apollo.free_account}));setKey('')},'Clave de Apollo guardada. Comprueba el acceso gratuito.')}><Busy busy={busy}/><Check size={15}/>Guardar Apollo</button><a href="https://app.apollo.io/#/settings/integrations/api" target="_blank" rel="noopener noreferrer">Obtener API key ↗</a></div>{apollo.configured&&<p className="hint" role="status">{apollo.access?.message||'Clave guardada; acceso a la búsqueda todavía sin comprobar.'}</p>}<button className="secondary small" disabled={busy||!apollo.configured} onClick={()=>void action(()=>api('/api/apollo/connection-check',post({})),'Comprobación de acceso terminada.')}><Busy busy={busy}/>Comprobar acceso gratuito</button><details className="settings-extra"><summary>Correo y teléfono · opcional</summary><p>Completar estos datos requiere cuota gratuita. Con presupuesto cero, el enriquecimiento permanece bloqueado.</p><label>Presupuesto gratuito por ciclo<input type="number" min={0} max={100000} value={apollo.free_budget} onChange={e=>setApollo(a=>({...a,free_budget:Number(e.target.value)}))}/></label><label className="checkbox-label"><input type="checkbox" checked={apollo.free_account} onChange={e=>setApollo(a=>({...a,free_account:e.target.checked}))}/>Mi cuenta utiliza la cuota gratuita, sin recargas automáticas</label><button className="secondary small" disabled={busy||!apollo.configured} onClick={()=>void action(async()=>setBalance(await api('/api/apollo/balance')),'Saldo consultado.')}>Comprobar saldo</button>{balance!==null&&<pre className="config-code">{JSON.stringify(balance,null,2)}</pre>}<p>Teléfonos pendientes: {apollo.pending}. Se comprueba el saldo antes de completar datos.</p></details></section>
    </div><div className="settings-footnote"><Check size={15}/><span>Las claves se guardan en este equipo y se utilizan exclusivamente en el servidor.</span></div></>}
    {tab==='profile'&&<><div className="settings-section-heading"><h2>Tu nombre en las conversaciones</h2><p>Se añade automáticamente al registrar llamadas, mensajes y comentarios.</p></div><section className="settings-card settings-narrow"><div className="settings-card-heading"><div className="settings-provider-icon"><Users size={20}/></div><div><h3>Responsable comercial</h3><p>Tu autoría en el historial compartido</p></div></div><label>Tu nombre para las interacciones<input maxLength={100} value={actor} onChange={e=>setActor(e.target.value)} placeholder="Ej. Marco"/></label><div className="settings-card-actions"><button className="primary small" disabled={busy||!actor.trim()} onClick={()=>void action(()=>api('/api/settings/actor',post({actor})),'Responsable guardado.')}><Busy busy={busy}/><Check size={15}/>Guardar responsable</button></div></section></>}
    {tab==='model'&&<><div className="settings-section-heading"><h2>Extracción en tu ordenador</h2><p>El modelo ayuda automáticamente cuando una página es difícil de interpretar.</p></div><section className="settings-card settings-narrow"><div className="settings-card-heading"><div className="settings-provider-icon"><LoaderCircle size={20}/></div><div><h3>Modelo local de Hugging Face</h3><p>Qwen3.5 · funciona sin Ollama</p></div><span className={'settings-pill '+(localModel?.ready?'ready':'')}>{localModel?.ready?'Listo':localModel?.installed?'Iniciando':'Sin instalar'}</span></div><p className="settings-description">{localModel?.ready?'El modelo está preparado. No necesitas activarlo en cada búsqueda.':localModel?.installed?'El motor local se está iniciando. La búsqueda convencional sigue disponible.':'La búsqueda convencional está disponible. Instala el modelo una vez para añadir ayuda local.'}</p><div className="settings-facts"><span><Check size={15}/>Sin coste por tokens de IA</span><span><Check size={15}/>Datos procesados en tu equipo</span><span><Check size={15}/>Solo propuestas con evidencia</span></div>{localModel?.error&&<ErrorBox error={localModel.error}/>}<div className="settings-card-actions"><button className="secondary small" onClick={()=>void action(load,'Estado del modelo actualizado.')} disabled={busy}><RefreshCw size={15}/>Comprobar estado</button></div>{!localModel?.installed&&<details className="settings-extra"><summary>Instalar el modelo en este equipo</summary><p>Ejecuta <code>.\.venv\Scripts\python.exe install-local-model.py</code> en la carpeta del proyecto y reinicia la aplicación.</p></details>}</section></>}
    {tab==='data'&&<><div className="settings-section-heading"><h2>Tu agenda se conserva</h2><p>Contactos, notas y guiones se guardan automáticamente después de cada cambio.</p></div><div className="settings-grid"><section className="settings-card"><div className="settings-card-heading"><div className="settings-provider-icon"><FileText size={20}/></div><div><h3>Copias y exportación</h3><p>Continúa en otra copia del proyecto</p></div><span className={'settings-pill '+(!shared?.error?'ready':'')}>{shared?.error?'Revisar':'Guardado local'}</span></div><p className="settings-description">Puedes descargar la agenda completa o preparar la copia que compartes con tu equipo.</p><div className="settings-data-actions"><a className="primary small" href="/api/crm/contacts/export?status=all"><ArrowDownToLine size={15}/>Descargar contactos CSV</a><button className="secondary small" disabled={busy||running} onClick={()=>void action(()=>api('/api/shared/export',post({})).then(r=>{if(!(r as {ok:boolean}).ok)throw new Error((r as {error:string}).error)}),'Copia portable y CSV guardados.')}><RefreshCw size={15}/>Guardar copia compartida</button><button className="secondary small" disabled={busy||running} onClick={()=>void action(()=>api('/api/shared/import',post({})),'Archivos compartidos revisados.')}>Importar cambios del equipo</button></div>{shared?.error&&<ErrorBox error={shared.error}/>}<details className="settings-extra"><summary>Cómo compartir la copia</summary><p>Los archivos se generan en <code>shared-data/</code>. Inclúyelos al actualizar el repositorio. Otra instalación los importa al arrancar. Las claves no se comparten y las copias no se sincronizan en tiempo real.</p></details></section><section className="settings-card"><div className="settings-card-heading"><div className="settings-provider-icon"><FileText size={20}/></div><div><h3>Revisiones pendientes</h3><p>Comprueba los cambios contradictorios</p></div><span className="settings-pill">{shared?.conflicts.length||0}</span></div>{!shared?.conflicts.length&&<p className="settings-description">No hay conflictos pendientes de revisión.</p>}{shared?.conflicts.map(c=><article className="shared-conflict" key={c.uuid}><h4>Revisión · {c.kind}</h4><details className="settings-extra"><summary>Comparar datos</summary><div className="comparison"><div><strong>En esta copia</strong><pre>{JSON.stringify(c.data.local,null,2)}</pre></div><div><strong>Archivo recibido</strong><pre>{JSON.stringify(c.data.incoming,null,2)}</pre></div></div></details><div className="settings-card-actions"><button className="secondary small" disabled={busy||running} onClick={()=>void action(()=>api('/api/shared/conflicts/'+c.uuid+'/resolve',post({choice:'local'})),'Se ha conservado el registro local.')}>Conservar local</button>{!['apollo','invalid'].includes(c.kind)&&<button className="secondary small" disabled={busy||running} onClick={()=>void action(()=>api('/api/shared/conflicts/'+c.uuid+'/resolve',post({choice:'incoming'})),'Datos externos aplicados.')}>Usar datos externos</button>}</div>{c.kind==='apollo'&&<p>Corrige los datos desde la ficha del contacto antes de cerrar esta revisión.</p>}</article>)}</section></div></>}
    </div>
  </div>
}

export function NextBatchDialog({run,onClose,onStart}:{run:Run;onClose:()=>void;onStart:(r:Run)=>void}) {
  const [preview,setPreview]=useState<{keywords:string;queries:Query[];parent_run_id:number;exhausted:boolean}|null>(null),[firms,setFirms]=useState(''),[people,setPeople]=useState(''),[advanced,setAdvanced]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('')
  useEffect(()=>{void api<typeof preview>('/api/searches/'+run.id+'/next-batch').then(p=>{setPreview(p);setFirms(p?.queries.filter(q=>q.phase==='firms').map(q=>q.text).join('\n')||'');setPeople(p?.queries.filter(q=>q.phase==='people').map(q=>q.text).join('\n')||'')}).catch(e=>setError(message(e)))},[run.id])
  const lines=(s:string)=>s.split('\n').map(v=>v.trim()).filter(Boolean)
  const queries:Query[]=[...lines(firms).map(text=>({text,phase:'firms' as const})),...lines(people).map(text=>({text,phase:'people' as const}))]
  async function start(){setBusy(true);setError('');try{onStart(await api<Run>('/api/searches',post({keywords:preview?.keywords||run.keywords,queries,parent_run_id:preview?.parent_run_id||run.id})));onClose()}catch(e){setError(message(e))}finally{setBusy(false)}}
  return <Modal title="Preparar siguiente lote" subtitle="Avanza por gestoras y mercados con consultas que aún no se han completado." onClose={onClose} wide><p>Se continuará buscando con <strong>{preview?.keywords||'renta variable'}</strong>, usando consultas nuevas y conservando lo encontrado.</p><button className="text-button" aria-expanded={advanced} onClick={()=>setAdvanced(v=>!v)}>Ver consultas avanzadas</button>{advanced&&<div className="query-grid"><label>Descubrir gestoras<textarea rows={5} value={firms} onChange={e=>setFirms(e.target.value)}/></label><label>Encontrar decisores<textarea rows={5} value={people} onChange={e=>setPeople(e.target.value)}/></label></div>}<p className="hint">{queries.length} líneas preparadas. Máximo 20 consultas; cada consulta básica nueva consume un crédito de Tavily. Los perfiles ya contactados se omiten.</p>{preview?.exhausted&&<div className="notice">No quedan consultas nuevas en los mercados preparados. Puedes editar las palabras clave en una nueva búsqueda.</div>}<ErrorBox error={error}/><div className="modal-actions"><button className="secondary" onClick={onClose}>Cancelar</button><button className="primary" disabled={busy||!queries.length||queries.length>20} onClick={()=>void start()}><Busy busy={busy}/><Search size={16}/>Iniciar siguiente lote</button></div></Modal>
}

export function PublicDataWorkspace({scanning,onRefresh}:{scanning:ScanningState|null;onRefresh:()=>void}){
  const [busy,setBusy]=useState(false),[error,setError]=useState(''),[continuous,setContinuous]=useState(true)
  async function start(){setBusy(true);setError('');try{await api('/api/public/searches',post({continuous}));onRefresh()}catch(e){setError(message(e))}finally{setBusy(false)}}
  return <section className="panel public-data-workspace"><h2>Correos, LinkedIn y teléfonos</h2><p>Revisa las webs corporativas, los equipos y las biografías de las personas que hay en tu agenda. Guarda cada dato con su fuente y omite a quienes ya has contactado.</p><p className="hint">Lectura de páginas públicas, sin Apollo ni créditos de búsqueda. La disponibilidad depende de lo que cada gestora publique. La búsqueda web descubre gestoras y alimenta este escaneo.</p><label className="checkbox-label"><input type="checkbox" checked={continuous} onChange={e=>setContinuous(e.target.checked)}/>Continuar revisando nuevas personas</label><ErrorBox error={error}/><button className="primary" disabled={busy||scanning?.public?.enabled} onClick={()=>void start()}><Busy busy={busy}/><Search size={16}/>Buscar datos de contacto</button>{scanning?.public?.enabled&&<p role="status">{scanning.public.status==='queued'?'En cola: empezará al terminar el lote activo.':scanning.public.reason||'Escaneo de datos públicos activado.'}</p>}</section>
}
